functions._demoPhaseDoc:
function _demoPhaseDoc(n) {
  if (n === 2) {
    // TODO: replace with Flat-OPC of phase2.docx when provided.
    return {
      kind: "placeholder",
      title: "PHASE 2 — SERVICES AGREEMENT (PLACEHOLDER)",
      paragraphs: [
        "[Placeholder document — will be replaced by phase2.docx]",
        "This Services Agreement (this “Agreement”) is entered into as of the date of last signature below (the “Effective Date”) by and between Colgate-Palmolive Company and [[Third Party Name]].",
        "1. Services. Provider shall perform the services described in the attached Statement of Work (the “Services”).",
        "2. Fees. In consideration of the Services, Company shall pay Provider $[[Total Fee]], due as $![[Payment Schedule]].",
        "3. Term. This Agreement expires on [[Expiration Date]] unless earlier terminated in accordance with its terms.",
        "OARS",
      ],
    };
  }
  if (n === 3) {
    // TODO: replace with Flat-OPC of phase3.docx when provided.
    return {
      kind: "placeholder",
      title: "PHASE 3 — MASTER SERVICES AGREEMENT (PLACEHOLDER)",
      paragraphs: [
        "[Placeholder document — will be replaced by phase3.docx]",
        "This Master Services Agreement (this “Agreement”) establishes the framework under which the parties may enter into separate Statements of Work.",
        "1. Statements of Work. Each SOW shall reference this Agreement and describe the services, deliverables, fees, and timeline.",
        "2. Fees. Fees are set forth in each SOW. Payment terms: $![[Payment Schedule]].",
        "3. Term. The initial term runs through [[Expiration Date]].",
        "OARS",
      ],
    };
  }
  return {
    kind: "placeholder",
    title: "PHASE 1 — DEMO DOCUMENT (PLACEHOLDER)",
    paragraphs: [
      "[Placeholder document for Phase 1 — content to be provided]",
      "Welcome to the ELI training demo. This document stands in for the Phase 1 agreement.",
      "This Consulting Agreement is entered into by and between Colgate-Palmolive Company and [[Consultant Name]].",
      "1. Engagement. Company engages Consultant to perform the services described herein.",
      "2. Compensation. Company shall pay Consultant $[[Total Fee]] for the services.",
      "OARS",
    ],
  };
}

jsonTools.init:
function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var STATE_KEY = "demo_active_phase";

  var PHASES = [
    { n: 1, label: "Phase 1", agreement: "Demo Document", points: "Intro agreement — placeholder content for now." },
    { n: 2, label: "Phase 2", agreement: "Services Agreement", points: "Will be the phase2.docx agreement." },
    { n: 3, label: "Phase 3", agreement: "Master Services Agreement", points: "Will be the phase3.docx agreement." },
  ];

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }
  function _mount() { return document.getElementById("_eli3_dashboard_root"); }

  function _getActivePhase() {
    return eli.events.safeAsync(eli.storage.get(STORE, STATE_KEY), "demo.state_read")
      .then(function (row) { return (row && row.phase) || 0; })
      .catch(function () { return 0; });
  }
  function _setActivePhase(n) {
    return eli.events.safeAsync(
      eli.storage.put(STORE, { key: STATE_KEY, phase: n, ts: Date.now() }),
      "demo.state_write"
    ).catch(function () {});
  }

  // Wipe the body and insert the phase document. Placeholder docs insert
  // as styled paragraphs; real docs (kind "ooxml") insert verbatim so
  // formatting + embedded OARS tables arrive exactly as authored.
  function _loadPhaseDoc(doc) {
    return eli.host.runRaw("demo:load_phase", function (context) {
      var body = context.document.body;
      if (doc.kind === "ooxml") {
        body.insertOoxml(doc.flatOpc, "Replace");
        return context.sync();
      }
      body.clear();
      var title = body.insertParagraph(doc.title || "DEMO DOCUMENT", "End");
      try { title.styleBuiltIn = "Heading1"; } catch (_e) {}
      (doc.paragraphs || []).forEach(function (t) {
        body.insertParagraph(String(t), "End");
      });
      return context.sync();
    });
  }

  function _onPhaseClick(phase, row) {
    eli.events.safeAsync(eli.ui.confirm({
      title: "Load " + phase.label + "?",
      message: "This will REPLACE everything in the current Word document with the " +
        phase.label + " agreement (" + phase.agreement + "). Continue?",
    }), "demo.confirm").then(function (ok) {
      if (!ok) return;
      var doc = (typeof window._demoPhaseDoc === "function") ? window._demoPhaseDoc(phase.n) : null;
      if (!doc) { _toast("Phase " + phase.n + " document missing from bundle.", "err"); return; }
      var btn = row.querySelector("[data-act='load']");
      if (btn) { btn.disabled = true; btn.textContent = "⏳ Loading…"; }
      eli.events.safeAsync(_loadPhaseDoc(doc), "demo.load_phase")
        .then(function () {
          eli.log.event("tool", "demo_phase_loaded", { phase: phase.n, kind: doc.kind });
          _toast("📄 " + phase.label + " document loaded.", "ok");
          return _setActivePhase(phase.n);
        })
        .then(function () { _show(); })
        .catch(function (err) {
          eli.log.event("tool", "demo_phase_load_failed", { phase: phase.n, msg: err && err.message });
          _toast("Load failed: " + (err && err.message || "unknown"), "err");
          if (btn) { btn.disabled = false; btn.textContent = "LOAD"; }
        });
    });
  }

  function _show() {
    var m = _mount();
    if (!m) { _toast("Dashboard root missing", "err"); return; }
    _getActivePhase().then(function (active) {
      m.innerHTML = "";
      var root = document.createElement("div");
      root.style.cssText = "background:#f1f5f9; min-height:100%; font:500 13px/1.45 'Inter','Segoe UI',sans-serif; color:#0f172a;";
      var rows = PHASES.map(function (p) {
        var isActive = active === p.n;
        var isReal = false;
        try { isReal = window._demoPhaseDoc && window._demoPhaseDoc(p.n).kind === "ooxml"; } catch (_e) {}
        return '<div data-phase="' + p.n + '" style="background:#fff; border:1px solid ' + (isActive ? "#c9a227" : "#e2e8f0") + '; border-left:4px solid ' + (isActive ? "#c9a227" : "#cbd5e1") + '; border-radius:8px; padding:14px 16px; margin-bottom:12px; display:flex; align-items:center; gap:14px;' + (isActive ? "box-shadow:0 2px 10px rgba(201,162,39,0.18);" : "") + '">' +
          '<div style="flex:0 0 auto; width:44px; height:44px; border-radius:8px; background:linear-gradient(135deg,#0d1b2a,#1b263b); color:#f2d866; display:flex; align-items:center; justify-content:center; font:800 18px/1 Georgia,serif; border:1px solid #c9a227;">' + p.n + '</div>' +
          '<div style="flex:1; min-width:0;">' +
            '<div style="font:800 13px/1.2 Inter,sans-serif; color:#0f172a;">' + _esc(p.label) + ' · ' + _esc(p.agreement) +
              (isActive ? ' <span style="color:#16a34a; font-weight:800;">✓ LOADED</span>' : '') +
              (isReal ? '' : ' <span style="font:700 9px/1 Inter,sans-serif; color:#92400e; background:#fef3c7; padding:2px 6px; border-radius:8px; vertical-align:middle;">PLACEHOLDER</span>') +
            '</div>' +
            '<div style="font:500 11.5px/1.4 Inter,sans-serif; color:#64748b; margin-top:3px;">' + _esc(p.points) + '</div>' +
          '</div>' +
          '<button data-act="load" type="button" style="flex:0 0 auto; padding:9px 18px; border:none; border-radius:8px; background:linear-gradient(135deg,#c9a227,#dbb846); color:#fff; font:800 11px/1 Inter,sans-serif; letter-spacing:0.06em; cursor:pointer; box-shadow:0 2px 6px rgba(201,162,39,0.3);">' + (isActive ? "RELOAD" : "LOAD") + '</button>' +
        '</div>';
      }).join("");
      root.innerHTML =
        '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%); border-bottom:2px solid #c9a227; padding:14px 20px; display:flex; align-items:center; gap:12px; position:sticky; top:0; z-index:5;">' +
          '<button data-act="back" title="Back" style="border:1px solid rgba(255,255,255,0.25); background:rgba(255,255,255,0.06); border-radius:6px; padding:4px 10px; cursor:pointer; font-size:14px; color:#e2e8f0;">←</button>' +
          '<div style="font:800 15px/1 Georgia,serif; color:#fff;">🎬 Demo Director</div>' +
          '<div style="flex:1"></div>' +
          '<div style="font:700 9px/1 Inter,sans-serif; color:#c9a227; letter-spacing:0.14em;">TRAINING</div>' +
        '</div>' +
        '<div style="padding:20px 22px; max-width:760px; margin:0 auto;">' +
          '<div style="font:500 12px/1.5 Inter,sans-serif; color:#475569; background:#fff; border:1px solid #e2e8f0; border-left:3px solid #c9a227; padding:10px 14px; border-radius:6px; margin-bottom:16px;">' +
            'Load a phase document, then tell the room: <b>“Exit ELI and reload it.”</b> ' +
            'The real boot-time OARS detection runs on reload — nothing is short-circuited.' +
          '</div>' +
          rows +
        '</div>';
      m.appendChild(root);
      var back = root.querySelector("[data-act='back']");
      if (back) back.onclick = function () {
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
      };
      PHASES.forEach(function (p) {
        var row = root.querySelector('[data-phase="' + p.n + '"]');
        if (!row) return;
        row.querySelector("[data-act='load']").onclick = function () { _onPhaseClick(p, row); };
      });
    });
  }

  eli.register({
    tile: { app_demo: function () {
      try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedDemo"); } catch (_) {}
      _show();
    } },
  });
}
